test('directory controls preserve ordinary declarations through save reopen and typed native payload',()=>{
  assert.deepEqual(plain(sandbox.parse({cdn_directory_reporting_enabled:false,cdn_directory_rules_text:'invalid'})),{});
  const saved={cdn_directory_reporting_enabled:true,cdn_directory_rules_text:'HTTPS://WWW.CDN.example/assets/\r\n\nhttp://files.example:8443/\n   \n'},reopened=sandbox.restore(JSON.parse(JSON.stringify(saved)));
