});
test('directory UI enforces exact count bytes and literal path declarations without grant objects',()=>{
  const prefix='https://cdn.example/',exact=prefix+'a'.repeat(2048-prefix.length-1)+'/';assert.equal(new TextEncoder().encode(exact).length,2048);
  assert.equal(plain(parse(exact)).cdn_directory_reporting.rules[0],exact);assert.throws(()=>parse(exact+'/'));
  const many=Array.from({length:32},(_,i)=>`https://cdn.example/d${i}/`);assert.equal(plain(parse(many.join('\n'))).cdn_directory_reporting.rules.length,32);assert.throws(()=>parse([...many,'https://cdn.example/more/'].join('\n')));
  const result=plain(parse('https://cdn.example/Assets/%2F/\nhttps://cdn.example/assets/%2f/\nhttp://cdn.example/a+b.(x)/'));
  assert.deepEqual(Object.keys(result),['cdn_directory_reporting']);assert.equal(result.resource_discovery,undefined);assert.equal(result.check_external,undefined);
  assert.equal(result.cdn_directory_reporting.rules[0],'https://cdn.example/Assets/%2F/');
});
test('directory page link provenance uses escaped existing consumer and UI has no JSON schema entry',()=>{
  const observation={engine:'own-engine',normalization:'own-profile',config_sha256:'a'.repeat(64),matching_rules:[{rule_index:0,declared_directory:'https://CDN.example/assets/'},{rule_index:2,declared_directory:'https://cdn.example/'}],seed_scope_internal:false,grants_network_or_credentials:false};
  const report=sandbox.report(observation);assert(report.includes('Regel 1: https://CDN.example/assets/')&&report.includes('Regel 3: https://cdn.example/'));assert(report.includes('Seed-Bereich: extern')&&report.includes('keine zusätzliche Abruf-/Traversierungs-/Headerfreigabe'));
  assert(sandbox.report(null).includes('nicht nachträglich'));
  assert(source.includes("['CDN-Verzeichniszuordnung', cdnDirectoryReportText(page.cdn_directory_reporting)]"));assert(source.includes('escape(cdnDirectoryReportText(link.cdn_directory_reporting))'));
  const section=html.slice(html.indexOf('name="cdn_directory_reporting_enabled"'),html.indexOf('<label class="setting-wide">URL-Include-Muster'));
  assert(section.includes('CDN-Verzeichnisadressen, eine pro Zeile')&&section.includes('name="cdn_directory_rules_text"'));assert(!section.includes('JSON')&&!section.includes('version'));
});

